package ds_lerc_test

import (
	"testing"

	lerc "github.com/flywave/go-lerc"
	"github.com/mocheer/pluto/pkg/ds"
)

func TestLerc(t *testing.T) {
	h := 257
	w := 257
	zImg := make([]float32, w*h)
	for i := range zImg {
		zImg[i] = 0
	}

	maskByteImg := make([]byte, w*h)
	for i := range maskByteImg {
		maskByteImg[i] = 0
	}

	maxZErrorWanted := 0.1
	eps := 0.0001
	maxZError := maxZErrorWanted - eps

	buff, err := lerc.Encode(zImg, 1, w, h, 1, maskByteImg, maxZError)
	if err != nil {
		t.Error(err)
	}

	if buff == nil {
		t.Error("error")
	}

	ds.Save("empty.lerc", buff)

}

func TestLerc_7_45_212(t *testing.T) {
	h := 257
	w := 257
	zImg := getTileData()

	maskByteImg := make([]byte, w*h)
	for i := range maskByteImg {
		if zImg[i] != 0 {
			maskByteImg[i] = 1
		} else {
			maskByteImg[i] = 0
		}
	}

	maxZErrorWanted := 0.1
	eps := 0.0001
	maxZError := maxZErrorWanted - eps

	buff, err := lerc.Encode(zImg, 1, w, h, 1, maskByteImg, maxZError)
	if err != nil {
		t.Error(err)
	}

	if buff == nil {
		t.Error("error")
	}

	ds.Save("7_45_212.lerc", buff)

}

